(() => {
  const script = document.currentScript;
  if (!script || document.querySelector('.library-back-link')) return;
  const materialTypes = { document: '文档资料', paper: '论文资料', video: '视频资料' };
  const materialType = materialTypes[script.dataset.materialType] || materialTypes.video;
  const link = document.createElement('a');
  link.className = 'library-back-link';
  link.href = new URL('index.html', script.src).href;
  link.textContent = '← 返回笔记索引';
  link.setAttribute('aria-label', '返回大模型学习笔记索引');
  const badge = document.createElement('span');
  badge.className = `library-material-badge ${materialType === '文档资料' ? 'is-document' : materialType === '论文资料' ? 'is-paper' : 'is-video'}`;
  badge.textContent = materialType;
  badge.setAttribute('aria-label', `资料类型：${materialType}`);
  const style = document.createElement('style');
  style.textContent = '.library-back-link,.library-material-badge{position:fixed;z-index:9999;border:1px solid rgba(119,137,160,.28);background:rgba(255,255,255,.92);box-shadow:0 8px 24px rgba(21,39,67,.14);backdrop-filter:blur(10px);font:700 12px/1.25 Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}.library-back-link{left:18px;bottom:18px;padding:9px 13px;border-radius:9px;color:#1f4f8f!important;text-decoration:none!important;transition:transform .18s ease,box-shadow .18s ease}.library-back-link:hover{transform:translateY(-2px);box-shadow:0 12px 30px rgba(21,39,67,.2)}.library-material-badge{right:18px;top:18px;padding:7px 11px;border-radius:999px;letter-spacing:.08em}.library-material-badge.is-document{color:#2f5d49;background:rgba(236,248,242,.94);border-color:rgba(53,125,91,.28)}.library-material-badge.is-paper{color:#6b4c08;background:rgba(255,248,216,.95);border-color:rgba(154,109,17,.3)}.library-material-badge.is-video{color:#5b438d;background:rgba(245,241,252,.94);border-color:rgba(117,82,174,.25)}body.dark .library-back-link{color:#dce9ff!important;background:rgba(17,28,45,.9);border-color:rgba(255,255,255,.18)}body.dark .library-material-badge{color:#e8edf7;background:rgba(17,28,45,.9);border-color:rgba(255,255,255,.18)}@media(max-width:640px){.library-back-link{left:10px;bottom:10px;padding:8px 10px;font-size:11px}.library-material-badge{right:10px;top:10px;font-size:10px}}@media print{.library-back-link,.library-material-badge{display:none}}';
  document.head.appendChild(style);
  document.body.appendChild(link);
  document.body.appendChild(badge);
})();
